use std::sync::{Arc, Condvar, Mutex};
use std::thread;
use std::time::Duration;

struct Semaphore {
    permits: Mutex<u32>,
    cv: Condvar,
}

impl Semaphore {
    fn new(count: u32) -> Self {
        Self {
            permits: Mutex::new(count),
            cv: Condvar::new(),
        }
    }

    fn acquire(&self) {
        let mut permits = self.permits.lock().unwrap();
        while *permits == 0 {
            permits = self.cv.wait(permits).unwrap();
        }
        *permits -= 1;
    }

    fn release(&self) {
        *self.permits.lock().unwrap() += 1;
        self.cv.notify_one();
    }
}

fn main() {
    let mtx_a = Arc::new(Mutex::new(()));
    let mtx_b = Arc::new(Mutex::new(()));
    let sem_a = Arc::new(Semaphore::new(0));
    let sem_b = Arc::new(Semaphore::new(0));

    let (ma, mb, sa, sb) = (
        Arc::clone(&mtx_a),
        Arc::clone(&mtx_b),
        Arc::clone(&sem_a),
        Arc::clone(&sem_b),
    );
    let worker_a = thread::spawn(move || {
        let ga = ma.lock().unwrap();
        sa.release();
        sb.acquire();
        let gb = mb.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    let (ma2, mb2, sa2, sb2) = (
        Arc::clone(&mtx_a),
        Arc::clone(&mtx_b),
        Arc::clone(&sem_a),
        Arc::clone(&sem_b),
    );
    let worker_b = thread::spawn(move || {
        // Acquire in the same global order as worker A to avoid deadlock.
        let ga = ma2.lock().unwrap();
        sb2.release();
        sa2.acquire();
        let gb = mb2.lock().unwrap();
        drop(gb);
        drop(ga);
    });

    thread::spawn(move || loop {
        thread::sleep(Duration::from_millis(10));
    });

    worker_a.join().unwrap();
    worker_b.join().unwrap();
}
```

Wait, but now there's a problem: worker A locks `mtx_a`, releases `sa`, then waits on `sb`. Worker B locks `mtx_a` — but A holds it. So B blocks on `mtx_a` before releasing `sb`. Then A waits on `sb` forever. Deadlock again!

So the handshake ordering matters. Let me think more carefully.

The handshake: A releases sa, waits sb. B releases sb, waits sa. For both to proceed past the handshake, both must release before either acquires. That works if the releases happen before the acquires. But if B blocks on `mtx_a` before releasing `sb`, then A never gets `sb`.

So the handshake must happen *before* any mutex acquisition. Let me put the handshake first:

Worker A: `sa.release(); sb.acquire();` then lock a, lock b.
Worker B: `sb.release(); sa.acquire();` then lock a, lock b.

Now: A releases sa, B releases sb. A acquires sb (ok), B acquires sa (ok). Both proceed. Then both lock a then b in same order — no deadlock. 

But wait — is there a race where A releases sa, then A acquires sb before B releases sb? A would block on sb until B releases it. B releases sb, then B acquires sa (already released by A). Fine. Both proceed. Good.

Let me verify: A: release sa (sa=1). B: release sb (sb=1). A: acquire sb (sb=0). B: acquire sa (sa=0). Both past handshake. Then A locks a, B locks a — one waits, then locks b. No deadlock. 

This preserves the "intermediate semaphore handshake" design intent (handshake between the two workers) and fixes the deadlock by ensuring the handshake completes before mutex acquisition, plus consistent lock ordering.

